from __future__ import annotationsfrom pathlib import Pathimport pandas as pdfrom scipy.stats import ks_2sampfrom ml_service.config import Config, load_configdef detect_drift(recent: pd.DataFrame, config: Config | None = None) -> dict:    cfg = config or load_config()    ref_path = Path(cfg.reference_data_path)    if not ref_path.exists():        raise FileNotFoundError(            f"No reference at {ref_path}. Run `python -m ml_service.model.train` first."        )    reference = pd.read_csv(ref_path)    per_feature = {}    drifted = []    for name in cfg.feature_names:        stat, p_value = ks_2samp(reference[name], recent[name])        is_drifted = bool(p_value < cfg.drift_threshold)        per_feature[name] = {            "ks_stat": float(stat),            "p_value": float(p_value),            "drifted": is_drifted,        }        if is_drifted:            drifted.append(name)    return {        "drift_detected": len(drifted) > 0,        "drifted_features": drifted,        "per_feature": per_feature,    }